// --- Reverend Insanity: the wolf tide (Fang Yuan's lead life). WS2: killing is common outside the walls. His Gu are items in his own
// inventory and his essence is his own reserve; the fight spends both for real and writes them back once, in its own commit.
export const WOLF_HUNT = Object.freeze({
    bladeForce: {value: 12, why: 'A Moonglow blade cuts by the Gu, not the arm: about two fifths of a wolf, so three clean throws kill one (the contest pack\'s moonglow_blade drops a crippled wolf in one; a healthy one takes more).'},
    boarForce: {value: 6, why: 'Authored: a boar\'s strength behind a fist, half a blade. Enough to kill a hurt wolf.'},
    moonblade: {value: 4, why: 'Four parts a throw (the contest pack\'s moonglow_blade row, ch122-123).'},
    jade: {value: 2, why: 'Authored: White Jade Gu holds while it is fed essence; two parts keep it up for one blow.'},
    boar: {value: 1, why: 'Authored: Black Boar Gu\'s strength is cheap to call on, one part a blow.'},
    woundCarried: {value: .7, why: 'Authored: a wound from the same night\'s patrol (the day report\'s injured fact) leaves about seven tenths of your health for the fight.'},
    hidden: {value: 7, why: 'Authored: the killer move pays both Gu at once, the blade\'s four and three for the Stealth Rock Gu to hide the gathering.'},
});
const ESSENCE = 'book.ri.lead.primeval';
const GU = {moonglow: RI_DAY_ITEMS.moonglow, jade: RI_DAY_ITEMS.whiteJade, boar: 'book.ri.lead.river_toad.refined_black_boar_gu', rock: 'book.ri.lead.stone_forest.stealth_rock_gu'};
const reserve = state => Number(state.simulation?.energies?.player?.[ESSENCE]?.reserve || 0);
// The patrol's report can say he came back hurt (daily-loops lane: fact `book.ri.lead.day.injured`); the fight then starts from that wound.
const INJURED = 'book.ri.lead.day.injured';
// The patrol's report can leave a wolf at the wall (daily-loops lane, RI_WOLF_AT_WALL owns its fact and merit). The patrol is pack data and
// cannot open a fight, so this opener is the trigger: with a wolf waiting it fights that wolf at night and settles the patrol's facts.
const wolfWaiting = state => !!riLeadDayFacts(state)['book.ri.lead.day.wolf_waiting'];
const PATROL_ID = 'ri-wolf-tide-patrol';
// Which wolf comes close is one keyed draw on the world's seed and the hour (same hour, same wolf on a replay).
// The wolf's size, health and bite come from the wolf tide's own table (ri_wolf_tide.js riWolfFoe: one keyed draw per hour, big wolves can be hunted out).
export const woundCarried = state => !!(state.actors?.player?.facts?.[INJURED] || riLeadDayFacts(state)[INJURED]);
export function wolfKit(state, context) {
    const hungry = !!riLeadDayFacts(state)['book.ri.lead.day.moonglow.hungry'];
    const blocked = hungry ? {blocked: 'The Moonglow Gu is hungry and will not cut. Feed it first.'} : {};
    const kit = {};
    if(held(context, GU.moonglow)) kit.moonblade = {label: 'Moonblade', text: 'Moonglow Gu throws a crescent of moonlight.', cost: 5, force: WOLF_HUNT.bladeForce.value, hit: 1.7, spends: {essence: WOLF_HUNT.moonblade.value}, ...blocked,
        why: `A thrown crescent of light from the Moonglow Gu. ${WOLF_HUNT.moonblade.why}`};
    if(held(context, GU.moonglow) && held(context, GU.rock)) kit.hidden_blade = {label: 'Stone-hidden moonblade', text: 'Killer move: the Stealth Rock Gu hides the gathering, then the Moonglow Gu cuts.', cost: 7, force: WOLF_HUNT.bladeForce.value, hit: 2.4,
        spends: {essence: WOLF_HUNT.hidden.value}, roles: [{role: 'hide the gathering', by: 'Stealth Rock Gu'}, {role: 'cut', by: 'Moonglow Gu'}], ...blocked,
        why: `A killer move as roles filled by Gu you hold (GP4; authored, not a book move): a wolf cannot dodge what it does not see coming. ${WOLF_HUNT.hidden.why}`};
    if(held(context, GU.boar)) kit.boar_fist = {label: 'Black Boar fist', text: 'A fist with a boar\'s strength behind it.', cost: 3, force: WOLF_HUNT.boarForce.value, spends: {essence: WOLF_HUNT.boar.value},
        why: `Black Boar Gu lends raw strength. A fist like that can kill. ${WOLF_HUNT.boar.why}`};
    if(held(context, GU.jade)) kit.jade_skin = {label: 'White Jade skin', text: 'White Jade Gu hardens your skin against the next bite.', cost: 2, ward: 7, spends: {essence: WOLF_HUNT.jade.value},
        why: `A guarding Gu: the next blow mostly glances off, and a cast at you is harder to land. ${WOLF_HUNT.jade.why}`};
    return kit;
}
registerTempoOpener({id: 'ri.wolf.tide', label: 'Hunt a lightning wolf on the tide (play it out)', meets: {kind: 'beast', preset: 'hunt', lethal: true},
    text: 'Instead of a compressed patrol, meet one lightning wolf beyond the wall and fight it move by move. A killed wolf leaves an eye for the alliance board.',
    owns: id => id === 'ri-wolf-tide' || id === PATROL_ID,
    quote(state, context) {
        if(state.actors?.player?.worldId !== 'book.ri.lead.world') return {visible: false};
        if(!held(context, GU.moonglow)) return {visible: false};
        if(busy(state)) return {visible: true, eligible: false, reason: 'Another encounter is already open.'};
        const parts = reserve(state), kit = wolfKit(state, context), waiting = wolfWaiting(state) ? 'The wolf from tonight\'s watch is at the wall. ' : '';
        if(kit.moonblade.blocked) return {visible: true, eligible: true, reason: `${waiting}${kit.moonblade.blocked} You can still go out with fists.${woundCarried(state) ? ' You carry tonight\'s wound into it.' : ''}`};
        return {visible: true, eligible: true, reason: `${waiting}${parts} parts of essence in your sea; a moonblade costs ${WOLF_HUNT.moonblade.value}.${woundCarried(state) ? ' You carry tonight\'s wound into it.' : ''} Outside the wall a blow that drops the wolf kills it.`};
    },
    spec(state, context, helpers) {
        const kit = wolfKit(state, context);
        const patrol = wolfWaiting(state), wolf = riWolfFoe(state), large = wolf.large;
        const startEssence = reserve(state);
        return {id: patrol ? PATROL_ID : 'ri-wolf-tide', title: patrol ? 'The wolf at the wall' : 'A lightning wolf beyond the wall', floor: 1, startEssence,
            conditions: {light: patrol ? 'dark' : 'day', footing: 'bad', place: patrol ? 'The village wall' : 'Beyond the wall'},
            stakes: {preset: 'hunt', stakes: 'the wolf\'s life, and wolf parts for the board', text: 'A hunt beyond the wall: the wolf fights for its life. A blow that drops it kills it; if it drops you, you wake badly hurt.',
                why: 'WS2: killing is common outside the walls; the tide is why you are here.'},
            fighters: [you(helpers, {moves: [...PLAIN, ...Object.keys(kit)], kit, means: {essence: startEssence}, meansLabels: {essence: 'essence'},
                ...(woundCarried(state) ? {hp: Math.max(1, Math.round(helpers.vitals.health * WOLF_HUNT.woundCarried.value * 10) / 10)} : {})}),
                foe(helpers, {id: 'ri.wolf.tide.wolf', name: large ? 'A large lightning wolf' : 'A lightning wolf', hp: wolf.hp, tags: large ? ['beast', 'large'] : ['beast'],
                    body: {attack: wolf.attack, agility: 5, dexterity: 6, intuition: 4, attack_speed: 1.1, defense: 1, crit_rate: .1, crit_multiplier: 1.5, attack_count: 1},
                    goals: {survive: .4, aim: .6}, moves: ['jab', 'swing', 'withdraw'], wants: 'It fights to eat, and runs when it is hurt enough.',
                    fateText: {finish: 'It dies. You can cut out its eye; the board pays for the eye.', spare: 'It limps back into the trees. The woods keep one more wolf.',
                        detail: 'One wolf eye to hand in at the alliance board.'}})]};
    },
    // Essence spent in the fight leaves the reserve once; a killed wolf leaves an eye the day's alliance board reads (FLR4: hand_in_eye).
    // From the patrol, it also frees the patrol, pays the kill merit, and leaves him injured when he was hurt or did not win (plain facts the
    // pack's rules read), plus a readable record for Reports and later readers.
    after(plan, result, b) {
        const me = b.fighters.player, left = me.means?.essence, pool = plan.state.simulation?.energies?.player?.[ESSENCE];
        const start = b.startEssence ?? reserve(plan.state);
        const spent = Number.isFinite(left) ? Math.max(0, start - left) : 0;
        if(pool && Number.isFinite(left)) pool.reserve = Math.max(0, pool.reserve - spent);
        const wolf = b.fighters['ri.wolf.tide.wolf'], killed = result === 'won' && wolf?.end === 'killed' ? 1 : 0;
        const inv = ((plan.gameplay ||= {}).player ||= {}).inventory ||= {}, add = (id, n) => { inv[key(id)] = (inv[key(id)] || 0) + n; };
        // Weibao, 2026-11-14: "Rather than merit immediately it could be like part of the wolf drops and then I can trade that in for merit".
        // A kill drops the wolf's parts (riWolfParts: eye, hide, meat in jin); the board pays for the eye. A wolf that lives (spared, held back,
        // driven off) leaves only the watch's tally from a patrol. No merit is written here: the alliance board is the one merit writer.
        const large = !!wolf?.tags?.includes('large'), parts = killed ? riWolfParts({large}) : {};
        for(const [part, n] of Object.entries(parts)) if(n > 0 && RI_WOLF_PART_ITEMS[part]) add(RI_WOLF_PART_ITEMS[part], n);
        if(parts.meat > 0) ((plan.state.simulation.knowledge ||= {}).player ||= {})[RI_MEAT_NOTE] = {stage: 'understood', value: `You carried ${parts.meat} jin of wolf meat back from beyond the wall.`, at: plan.state.clock, cause: `tempo:${b.id}`};
        if(killed) plan.state.actors.player.facts[RI_WOLF_TIDE_FACT] = riRecordWolfKill(plan.state, {large});
        // What he carries away, in player words, for the result line (PS26).
        plan.fightCarry = killed ? [`A wolf eye for the board${parts.pelt ? ', its hide' : ''}${parts.meat ? ` and ${parts.meat} jin of meat` : ''} are in your pack.`]
            : wolf?.end === 'knocked_out' ? ['The wolf limped off into the trees.'] : [];
        const facts = plan.state.actors.player.facts, wounded = Object.keys(me.parts || {}).length > 0;
        if(b.id === PATROL_ID) {
            facts[RI_WOLF_AT_WALL.fact] = false;
            // A wolf that lived still leaves the captain's word that you held the wall: one watch tally (the board pays it).
            if(!killed && result === 'won') { add(RI_WOLF_AT_WALL.tally, 1); plan.fightCarry.push('The watch captain gives you a tally for holding the wall.'); }
            if(wounded || result === 'lost' || result === 'withdrawn' || result === 'yielded') facts['book.ri.lead.day.injured'] = true;
        }
        facts['book.ri.lead.day.wolf_fight'] = JSON.stringify({from: b.id === PATROL_ID ? 'patrol' : 'hunt', result, killed, wolf: wolf?.end ?? (wolf?.status === 'left' ? 'withdrew' : 'stood'),
            essenceSpent: spent, healthMissing: Math.max(0, Math.round((me.maxHp - me.hp) * 10) / 10), wounded, at: plan.state.clock});
    },
});

// A wolf pack at a gap in the wall (TF4, MS7; Weibao, 2026-11-21: "implement entirely"). The tide's wolves come as one crowd: a blow lands
// on the wolf in front, Sweep reaches the front two, Single out drives a chosen wolf forward, and a hurt wolf at the front gives way to a
// fresher one. Each wolf is its own body, so every kill drops its own parts and counts against the tide (MS9). An original encounter beside
// canon (AD32), with authored dials.
export const WOLF_PACK = Object.freeze({
    size: {value: 5, why: 'Authored: a pack of five pressing a gap is a real crowd for one Gu Master, not a tide; fewer if the wall is thinned.'},
    least: {value: 2, why: 'Two or more wolves make a crowd; with fewer about, there is no pack to meet.'},
});
const PACK_ID = 'ri-wolf-pack';
const packSize = state => Math.min(WOLF_PACK.size.value, riWolfTideView(state).rows.find(r => r.id === RI_WOLF_SPECIES.ordinary)?.left ?? 0);
registerTempoOpener({id: 'ri.wolf.pack', label: 'Hold a gap in the wall against a wolf pack', meets: {kind: 'beast', preset: 'hunt', lethal: true},
    text: 'A pack of lightning wolves presses a gap in the wall. They come as one crowd: you can only reach the wolf in front, unless you sweep or drive one forward.',
    owns: id => id === PACK_ID,
    quote(state, context) {
        if(state.actors?.player?.worldId !== 'book.ri.lead.world') return {visible: false};
        if(!held(context, GU.moonglow)) return {visible: false};
        if(busy(state)) return {visible: true, eligible: false, reason: 'Another encounter is already open.'};
        const n = packSize(state);
        if(n < WOLF_PACK.least.value) return {visible: true, eligible: false, reason: 'The wolves at this stretch of wall are thinned; no pack is pressing the gap.'};
        return {visible: true, eligible: true, reason: `${n} wolves at the gap, coming as one pack. ${reserve(state)} parts of essence in your sea.${woundCarried(state) ? ' You carry tonight\'s wound into it.' : ''}`};
    },
    spec(state, context, helpers) {
        const kit = wolfKit(state, context), startEssence = reserve(state), n = packSize(state);
        const wolves = Array.from({length: n}, (_, i) => foe(helpers, {id: `ri.wolf.pack.${i + 1}`, name: 'Lightning wolf', hp: RI_WOLF_TIDE_DIALS.ordinaryHp.value, tags: ['beast'],
            body: {attack: RI_WOLF_TIDE_DIALS.ordinaryAttack.value, agility: 5, dexterity: 6, intuition: 4, attack_speed: 1.1, defense: 1, crit_rate: .1, crit_multiplier: 1.5, attack_count: 1},
            goals: {survive: .4, aim: .6}, moves: ['jab', 'swing'], wants: 'They fight to eat, as a pack; the front wolf takes the blows.',
            fateText: {finish: 'It dies. You can cut out its eye; the board pays for the eye.', spare: 'It limps back into the trees.', detail: 'One wolf eye to hand in at the alliance board.'}}));
        return {id: PACK_ID, title: 'A wolf pack at the gap', floor: 1, startEssence,
            conditions: {light: 'day', footing: 'bad', place: 'A gap in the wall'},
            stakes: {preset: 'hunt', stakes: 'the gap, and wolf parts for the board', text: 'A pack at a gap in the wall: the wolves fight for their lives, as one crowd. A blow that drops one kills it; if they drop you, you wake badly hurt.',
                why: 'WS2: killing is common outside the walls; the tide is why you are here.'},
            terms: {beast: 'finish'},
            crowds: [{id: 'pack', name: 'The wolf pack', members: wolves.map(w => w.id)}],
            fighters: [you(helpers, {moves: [...PLAIN, ...Object.keys(kit)], kit, means: {essence: startEssence}, meansLabels: {essence: 'essence'},
                ...(woundCarried(state) ? {hp: Math.max(1, Math.round(helpers.vitals.health * WOLF_HUNT.woundCarried.value * 10) / 10)} : {})}), ...wolves]};
    },
    // Essence leaves the reserve once; each killed wolf drops its own parts and counts against the tide.
    after(plan, result, b) {
        const me = b.fighters.player, left = me.means?.essence, pool = plan.state.simulation?.energies?.player?.[ESSENCE];
        const spent = Number.isFinite(left) ? Math.max(0, (b.startEssence ?? reserve(plan.state)) - left) : 0;
        if(pool && Number.isFinite(left)) pool.reserve = Math.max(0, pool.reserve - spent);
        const killed = Object.keys(b.fighters).filter(id => id.startsWith('ri.wolf.pack.') && b.fighters[id].end === 'killed').length;
        const inv = ((plan.gameplay ||= {}).player ||= {}).inventory ||= {}, add = (id, n) => { inv[key(id)] = (inv[key(id)] || 0) + n; };
        const parts = riWolfParts({large: false});
        for(const [part, n] of Object.entries(parts)) if(n > 0 && RI_WOLF_PART_ITEMS[part]) add(RI_WOLF_PART_ITEMS[part], n * killed);
        if(killed && parts.meat > 0) ((plan.state.simulation.knowledge ||= {}).player ||= {})[RI_MEAT_NOTE] = {stage: 'understood', value: `You carried ${parts.meat * killed} jin of wolf meat back from the gap.`, at: plan.state.clock, cause: `tempo:${b.id}`};
        if(killed) plan.state.actors.player.facts[RI_WOLF_TIDE_FACT] = riRecordWolfKill(plan.state, {n: killed});
        plan.fightCarry = killed ? [`${killed === 1 ? 'A wolf eye' : `${killed} wolf eyes`} for the board${parts.pelt ? ', hides' : ''}${parts.meat ? ` and ${parts.meat * killed} jin of meat` : ''} are in your pack.`] : [];
        const facts = plan.state.actors.player.facts;
        if(Object.keys(me.parts || {}).length || result === 'lost') facts['book.ri.lead.day.injured'] = true;
        facts['book.ri.lead.day.wolf_fight'] = JSON.stringify({from: 'pack', result, killed, essenceSpent: spent, healthMissing: Math.max(0, Math.round((me.maxHp - me.hp) * 10) / 10), at: plan.state.clock});
    },
});
